INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('profile', '{"name":"Moinak Ghosh","headline":"Senior Enterprise Architect · Agentic AI","eyebrow":"Senior Enterprise Architect · Capgemini · Paris","title_lead":"Architecture for the","title_accent":"agentic enterprise.","intro":"I design how large enterprise systems share data, and how AI agents can work inside them safely. Sixteen years in enterprise software, most of them on Salesforce and integration, taught me the first part. The second part I build myself: my own agents, connected to real systems through the Model Context Protocol (MCP).","photo_key":"","location":"Paris, France","email":"moinak023@gmail.com","linkedin":"","github":"","phone":"","show_phone":false,"open_to":"Open to conversations about enterprise architecture, Salesforce and agentic AI.","career_start":"2010-01-01","counter_title":"Building enterprise software since January 2010","counter_text":"From PHP and the first Force.com apps to multi-org Salesforce architecture and AI agents. The tools changed many times. The habit of finding the real problem before choosing a technology did not."}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('stats', '{"eyebrow":"In numbers","title":"What I work at","items":[{"id":"s1","value":"16+","label":"years designing and building enterprise software","icon":"clock"},{"id":"s2","value":"15+","label":"Salesforce orgs in scope of the data hub I designed","icon":"hub"},{"id":"s3","value":"11","label":"country markets running on one CORE CRM model","icon":"globe"},{"id":"s4","value":"9","label":"agents, agent skills and AI builds in my own ecosystem","icon":"bot"}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('principles', '{"eyebrow":"How I work","title":"Four habits behind every design","items":[{"id":"pr1","title":"Problem before product","text":"I start from the business problem and the end-to-end process, then choose the technology. Sometimes the answer is Salesforce. Sometimes it is not.","icon":"target"},{"id":"pr2","title":"The simplest design that works","text":"Fewer moving parts, standard features before custom code, and a design the team can still support after go-live.","icon":"layers"},{"id":"pr3","title":"Agents with guardrails","text":"An agent is only as useful as the limits around it: which data it may read, which actions need a human yes, and a record of everything it did.","icon":"shield"},{"id":"pr4","title":"Measure, then change","text":"As a Six Sigma Black Belt, I measure before I change anything, and I fix the root cause rather than the symptom.","icon":"chart"}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('agentic', '{"eyebrow":"Agentic AI","title":"My agent ecosystem","intro":"I do not only talk about AI agents. I build them, connect them to real systems through MCP, and design the guardrails around them: approval steps, activity logs and clear limits on what an agent may touch. Most of this is my own work, built in my own time. The rest are proofs of concept for enterprise delivery.","diagram_title":"How the pieces fit together","layers":[{"id":"l1","name":"Where I talk to them","icon":"mic","items":["Voice: \"Hey Xarvis\"","Web","Windows desktop","Android","WhatsApp","Claude and GitHub Copilot"]},{"id":"l2","name":"Agents and skills","icon":"bot","items":["Xarvis voice assistant","Xarvis for Salesforce","Build with Xarvis","Salesforce Case Agent","Principal Architect","Enterprise Doc"]},{"id":"l3","name":"Models","icon":"chip","items":["Claude Opus 5.5","Claude Sonnet 5.5","OpenAI Realtime voice","OpenAI Responses API"]},{"id":"l4","name":"MCP servers and tools","icon":"plug","items":["Salesforce MCP","Salesforce DX MCP","GitHub","Cloudflare","Google Workspace","Twilio"]},{"id":"l5","name":"Guardrails","icon":"shield","items":["Human approval levels","Live activity log","Blocked-app list","Signed in as the user (OAuth PKCE)","Encrypted text memory","Two-step change and build"]}],"items":[{"id":"a1","featured":true,"icon":"mic","status":"Phase 1 built","year":"2026","title":"Xarvis — personal voice assistant","tagline":"An always-on assistant that listens, talks back and acts across my laptop, my phone and the web.","summary":"Say \"Hey Xarvis\" and talk to it like a person. It can be interrupted mid-sentence, keeps one conversation going across web, desktop and Android, and acts through MCP connectors to GitHub, Cloudflare, Google Workspace and Salesforce. Everything it does is shown on screen as it happens.","highlights":["Two models, each doing what it does best: OpenAI''s realtime voice model for live speech, Claude Sonnet 5.5 for reasoning and tool use.","One private agent per invited user, running on Cloudflare Workers and Durable Objects.","Four approval levels: reading runs at once, changes need a spoken or tapped yes, deletions and payments need a fingerprint, and banking and password apps are blocked.","Designed to wake only on my voice, sleep after five minutes of silence, and keep history as encrypted text, never audio.","Phase 1 (server and web app) is built and covered by 28 unit tests and 36 end-to-end tests. The Windows and Android apps are next."],"stack":["Claude Sonnet 5.5","OpenAI Realtime","Cloudflare Agents SDK","Durable Objects","MCP"],"link":"","link_label":"","image_key":""},{"id":"a2","featured":false,"icon":"hub","status":"Working prototype","year":"2026","title":"Xarvis for Salesforce","tagline":"Plain-English requests run straight against a Salesforce org through MCP.","summary":"A Node.js agent on Claude Opus 5.5 that uses the Salesforce MCP server. Ask it to describe an object such as Project__c, check validation rules or work with records, and it does so as you.","highlights":["Signs in with OAuth and PKCE as the user, so sharing rules, object permissions and field-level security apply exactly as in the Salesforce UI.","Switches between orgs, and an activity panel logs every tool call.","Next step: enterprise API access and company hosting, so a delivery team can use it."],"stack":["Node.js","Salesforce MCP","Claude Opus 5.5","OAuth 2.0 PKCE","External Client App"],"link":"","link_label":"","image_key":""},{"id":"a3","featured":false,"icon":"doc","status":"Working skill","year":"2026","title":"Build with Xarvis","tagline":"A requirements agent that turns a mockup into everything a Salesforce team needs to build it.","summary":"Give it an HTML mockup, a Word or PDF requirement, an Excel sheet or plain text. It questions the business analyst in Salesforce terms and produces the BRD, solution and technical design, build plan, developer packs with test cases and package.xml, and full traceability, keeping every document current as answers arrive over weeks.","highlights":["Says what it thinks each field does and asks to be corrected, instead of asking 200 blank questions.","Its memory lives in files (index, open items, traceability), because a new chat remembers nothing.","\"Done\" is a mechanical check: every item needs its object, field, data type, source, save behaviour and failure behaviour.","Change and Build always take two steps: an impact report first, then a human yes.","Runs in Claude Projects and in GitHub Copilot."],"stack":["Claude","GitHub Copilot","Agent skills","Salesforce metadata"],"link":"","link_label":"","image_key":""},{"id":"a4","featured":false,"icon":"chat","status":"Proof of concept","year":"2026","title":"Salesforce Case Agent","tagline":"Customers write on WhatsApp in their own language. The agent works the case in Salesforce.","summary":"A multilingual WhatsApp agent on Cloudflare Workers. It understands the customer, then works with Salesforce cases directly through the REST API, with no middleware in between.","highlights":["Twilio for WhatsApp, the OpenAI Responses API for language and tool calls, direct Salesforce REST for data.","Phase 2 adds Twilio Voice and a hotel-booking flow."],"stack":["Cloudflare Workers","Twilio","OpenAI Responses API","Salesforce REST"],"link":"","link_label":"","image_key":""},{"id":"a5","featured":false,"icon":"target","status":"In use","year":"2026","title":"Principal Architect and Enterprise Doc","tagline":"My own architecture sparring partner and documentation engine, packaged as agent skills.","summary":"Principal Architect takes a one-line requirement and produces the full end-to-end architecture, or reviews a design and names real faults. It must verify every limit, price and version on the web before stating it, and it asks at most two questions at a time. Enterprise Doc turns notes into specs, runbooks and review-board documents in one house style, with a verification pass before delivery.","highlights":["Covers every system in the chain: data flow, integration pattern, failure handling, phasing.","Built so that a guess is never presented as a fact."],"stack":["Claude","Agent skills"],"link":"","link_label":"","image_key":""},{"id":"a6","featured":false,"icon":"plug","status":"Proof of concept","year":"2026","title":"Headless CRM over MCP","tagline":"An AI agent working with Salesforce metadata and data without anyone opening the UI.","summary":"Connected Claude Code to a Salesforce sandbox through the Salesforce DX MCP server to test a \"headless CRM\" for an enterprise programme, and explored Agentforce for enterprise use.","highlights":["Researched which data an agent may reach, how it is exposed to the agent, and what governance sits around it."],"stack":["Claude Code","Salesforce DX MCP","Agentforce"],"link":"","link_label":"","image_key":""},{"id":"a7","featured":false,"icon":"code","status":"In use","year":"2025–2026","title":"AI agents in Salesforce delivery","tagline":"Putting coding and documentation agents to work on a live enterprise programme.","summary":"I use GitHub Copilot with Claude models for autonomous Salesforce development, and I am exploring the Salesforce coding agent through GitHub Actions. With the client''s internal AI service I built proofs of concept that generate technical design documents automatically, and an agent that pulls leads from external systems into Salesforce with their context.","highlights":[],"stack":["GitHub Copilot","GitHub Actions","Generative AI","RAG and vector search"],"link":"","link_label":"","image_key":""},{"id":"a8","featured":false,"icon":"cloud","status":"Live","year":"2026","title":"Full-stack platforms built with AI","tagline":"Complete, tested applications built with Claude as my coding agent.","summary":"A community platform for my college batch (member directory, events, polls, albums and a full admin console), a private family site, a self-hosted encrypted password vault, and this portfolio. All run on Cloudflare, with sign-in, storage and automated tests.","highlights":[],"stack":["Cloudflare Workers","D1","R2","React","TypeScript","Claude"],"link":"","link_label":"","image_key":""},{"id":"a9","featured":false,"icon":"lab","status":"Next","year":"2026","title":"Two-model design agent","tagline":"One model designs, another questions it, and they agree before I see the answer.","summary":"My next build: Claude proposes a solution, an OpenAI model challenges it, and the two converge on one agreed design. The aim is a reviewer that is not grading its own work.","highlights":[],"stack":["Claude","OpenAI","Agent orchestration"],"link":"","link_label":"","image_key":""}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('work', '{"eyebrow":"Enterprise architecture","title":"Architecture I own","intro":"Most of my recent work is for Saint-Gobain, a global manufacturing group, through Capgemini. These are the designs I am responsible for.","items":[{"id":"w1","icon":"hub","client":"Saint-Gobain","period":"2024 – now","status":"Rolling out","title":"Enterprise data hub for 15+ Salesforce orgs","problem":"Country Salesforce orgs across Europe each keep their own customers and accounts. There is no master database, so one update may need to reach several countries, and every change must be traceable.","approach":"A hub-and-spoke design: each country org exchanges data only with a central hub, which routes every change to the right orgs with a complete audit trail. I presented and defended it at the architecture review board.","outcome":"The first bi-directional country flow is live in Romania, Poland is in user acceptance testing, and more markets follow.","tags":["Salesforce","Hub and spoke","Event-driven integration","Snowflake","Audit trail"]},{"id":"w2","icon":"layers","client":"Saint-Gobain","period":"2024 – now","status":"Live","title":"CORE CRM and country onboarding","problem":"Many countries need one shared CRM, yet each has its own processes and data.","approach":"I own the CORE Salesforce solution and designed a DevOps-driven onboarding framework that separates global processes from country needs, so a new country adopts CORE with minimal rework.","outcome":"Used across 11 country markets and treated as the backbone for rolling out CORE processes.","tags":["Multi-org","DevOps","Release governance","Git branching"]},{"id":"w3","icon":"database","client":"Saint-Gobain","period":"2024 – now","status":"Live","title":"Product information interface","problem":"Sales teams need accurate product data in Salesforce, and the source of truth is the product information system (PIM).","approach":"Designed the complete solution and the Salesforce–PIM interface as the central product information backbone.","outcome":"Live in Romania and Benelux, with France and Germany planned.","tags":["PIM","API integration","Data ownership"]},{"id":"w4","icon":"doc","client":"Saint-Gobain","period":"2024 – now","status":"Live","title":"Real-time document integration with SAP","problem":"Salesforce users need documents that are held in SAP BTP Document Management.","approach":"Designed and implemented a real-time integration between SAP BTP DMS and Salesforce.","outcome":"","tags":["SAP BTP","Real-time integration","REST"]},{"id":"w5","icon":"sync","client":"L''Oréal","period":"Capgemini","status":"Delivered","title":"Two-way sync between independent Salesforce orgs","problem":"Two Salesforce orgs with different data models and business rules had to stay in step in real time.","approach":"Architected and delivered a bi-directional synchronisation using Change Data Capture and a middleware layer, with clear ownership rules for every field.","outcome":"Recognised by stakeholders as a complex delivery, with rollout to other countries in the pipeline.","tags":["Change Data Capture","Bi-directional sync","Middleware"]},{"id":"w6","icon":"people","client":"Enterprise programme","period":"2026","status":"Designed","title":"Five country orgs into one global org","problem":"Merging five country orgs creates duplicate customers and colliding identifiers.","approach":"Designed the migration around a golden record for every customer, built by a four-layer matching pipeline, with a phased migration plan.","outcome":"Design and migration plan ready for delivery.","tags":["Data migration","Deduplication","Golden record"]}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('experience', '{"eyebrow":"Experience","title":"Sixteen years, four companies","intro":"From developer to enterprise architect, almost all of it on Salesforce and the systems around it, for clients in Europe, the UK and the USA.","items":[{"id":"e1","company":"Capgemini","role":"Senior Enterprise Architect (Managing Solution Architect)","place":"India, then Paris since 2023","start":"2016-11","end":"","summary":"Architecture owner for multi-country Salesforce programmes, technical escalation point across countries, and lead for architecture reviews and integration governance.","points":["Saint-Gobain — Technical Architect: CORE CRM, enterprise data hub, PIM and SAP integrations, AI proofs of concept.","IMERYS — Technical Architect and Engagement Manager: custom Salesforce solutions on Manufacturing Cloud.","Sodexo — Technical Lead: design, estimation, code reviews and deployment governance for enterprise CRM.","L''Oréal — Technical Lead: real-time two-way sync between two independent Salesforce orgs.","Stellantis (PSA) — Project Manager and Technical Lead for Salesforce support and enhancements."]},{"id":"e2","company":"Tata Consultancy Services","role":"IT Analyst","place":"India","start":"2014-07","end":"2016-10","summary":"Led Salesforce development, integration and migration projects, and owned release management.","points":["Clients: Diageo (UK) and Toyota Financial Services (USA)."]},{"id":"e3","company":"Primalink Solutions","role":"Senior Application Developer","place":"India","start":"2011-06","end":"2014-06","summary":"Built Salesforce applications and integrations, including an AppExchange managed package taken through the Salesforce security review.","points":["Corporate Payment Hub: an ISV app for electronic payments, licensed through LMA and LMO.","Clients: Manchester City FC, MezzVest, Vitesse Media and Prestige Network."]},{"id":"e4","company":"Alliant Technologies","role":"Software Developer","place":"India","start":"2010-01","end":"2011-02","summary":"Built CRM and inventory management systems in PHP, JavaScript and MySQL.","points":[]}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('skills', '{"eyebrow":"Skills","title":"What I bring to a programme","groups":[{"id":"g1","name":"Agentic AI","icon":"bot","items":["AI agents","Model Context Protocol (MCP)","Claude Opus and Sonnet","OpenAI Realtime and Responses API","Agent skills","Human-in-the-loop approvals","RAG and vector search","AI coding agents","Agentforce"]},{"id":"g2","name":"Architecture","icon":"layers","items":["Enterprise architecture","Solution architecture","Multi-org strategy","Hub-and-spoke design","Architecture review boards","Estimation and roadmaps"]},{"id":"g3","name":"Salesforce","icon":"cloud","items":["Sales and Service Cloud","Manufacturing Cloud","Data Cloud","Apex","Lightning Web Components","Flows","Security and sharing model","AppExchange ISV packaging"]},{"id":"g4","name":"Integration and data","icon":"flow","items":["REST and SOAP APIs","Event-driven integration","Change Data Capture","Bi-directional sync","SAP BTP","PIM","Snowflake","Data migration and deduplication"]},{"id":"g5","name":"Cloud and DevOps","icon":"code","items":["Cloudflare Workers, D1 and R2","GitHub Actions","Git branching strategy","Salesforce DX","Release governance","Node.js and TypeScript","React"]},{"id":"g6","name":"Leadership","icon":"people","items":["Technical leadership","Engagement management","Stakeholder management","Mentoring","Six Sigma problem solving"]}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('certifications', '{"eyebrow":"Certifications","title":"Certified","items":[{"id":"c1","name":"Salesforce Certified Data Cloud Consultant","issuer":"Salesforce","year":"","link":"","icon":"award"},{"id":"c2","name":"Salesforce Certified Platform App Builder","issuer":"Salesforce","year":"","link":"","icon":"award"},{"id":"c3","name":"Elements of an AI Architect","issuer":"Skillsoft","year":"","link":"","icon":"bot"},{"id":"c4","name":"Generative AI","issuer":"Google","year":"","link":"","icon":"spark"},{"id":"c5","name":"Six Sigma Black Belt","issuer":"PMI and LinkedIn","year":"","link":"","icon":"chart"},{"id":"c6","name":"Connected Manager Program","issuer":"Harvard","year":"","link":"","icon":"people"},{"id":"c7","name":"Technical Architect (L0)","issuer":"Capgemini","year":"","link":"","icon":"layers"},{"id":"c8","name":"Engagement Manager (EM0)","issuer":"Capgemini","year":"","link":"","icon":"briefcase"}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('recommendations', '{"eyebrow":"Recommendations","title":"What colleagues say","intro":"From my LinkedIn recommendations.","items":[{"id":"r1","visible":true,"name":"Debashis Pyne, CSM","role":"Primalink Solutions","relation":"Recommended my work as Senior Application Developer at Primalink","date":"November 2013","text":"Moinak was one of our finds for Primalink''s development team. Since his inception, he had always demonstrated a hunger for knowledge and technical growth which in turn helped him to grasp advanced technologies. I found him very hard working, sincere and dedicated towards his work. He was a perfect team player well.\n\nI wish him all the very best for his future career!!"}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('education', '{"items":[{"id":"ed1","degree":"Bachelor of Technology, Electronics and Communication Engineering","school":"West Bengal University of Technology","year":"2009"}],"languages":[{"id":"la1","name":"English","level":"Professional"},{"id":"la2","name":"Bengali","level":"Native"},{"id":"la3","name":"Hindi","level":"Fluent"},{"id":"la4","name":"French","level":"Learning"}]}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('contact', '{"eyebrow":"Contact","title":"Let''s talk","text":"I enjoy hard architecture problems: many systems, many countries, and now AI agents that must work safely inside them. If that sounds like yours, write to me."}', 1791936000000);
INSERT OR IGNORE INTO blocks (key, data, updated_at) VALUES ('seo', '{"title":"Moinak Ghosh — Senior Enterprise Architect · Agentic AI","description":"Senior Enterprise Architect with 16 years on Salesforce and enterprise integration, building AI agents that connect to real systems through MCP. Based in Paris.","index":true}', 1791936000000);
